```
if (bike.dead) {
  bike.vy += GRAVITY*dt;
  bike.x += bike.vx*dt*0.4;
  bike.y += bike.vy*dt;
  bike.angle += bike.angVel*dt;
  const gy = terrain.yAt(bike.x) - WHEEL_R*0.5;
  if (bike.y > gy) { bike.y = gy; bike.vy *= -0.3; bike.angVel *= 0.6; } // bounce body
  crashTimer -= dt;
  if (crashTimer <= 0) gameOver();
