Now the audio. Engine:
```
class Audio {
  constructor(){ this.ctx=null; this.master=null; this.engineGain=null; this.engineOsc=null; this.filter=null; this.muted=false; }
  ensure(){
    if (this.ctx) { if (this.ctx.state==='suspended') this.ctx.resume(); return; }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ctx = new AC();
    this.ctx = ctx;
    this.master = ctx.createGain(); this.master.gain.value = this.muted?0:0.5; this.master.connect(ctx.destination);
    // engine
    const osc = ctx.createOscillator(); osc.type='sawtooth'; osc.frequency.value=60;
    const filter = ctx.createBiquadFilter(); filter.type='lowpass'; filter.frequency.value=320; filter.Q.value=2;
    const gain = ctx.createGain(); gain.gain.value=0;
    osc.connect(filter); filter.connect(gain); gain.connect(this.master); osc.start();
    this.engine = {osc, filter, gain};
    // second oscillator for rumble
  }
  engine(speed, active){
    if(!this.ctx||!this.engine) return;
    const t=this.ctx.currentTime;
    const norm = Math.min(1, Math.abs(speed)/640);
    this.engine.osc.frequency.setTargetAtTime(48 + norm*120, t, 0.08);
    this.engine.filter.frequency.setTargetAtTime(240 + norm*900, t, 0.1);
    this.engine.gain.gain.setTargetAtTime(active ? 0.05 + norm*0.09 : 0, t, 0.12);
  }
  blip(freq, dur, type='triangle', vol=0.2, slideTo){...}
  jump(){ this.blip(320,0.18,'square',0.12, 520); }
  land(){ this.blip(120,0.15,'sine',0.3, 60); }
  crash(){ noise burst? }
  trick(){ arpeggio }
}
```
