Helper:
```
const clamp=(v,a,b)=>v<a?a:v>b?b:v;
const lerp=(a,b,t)=>a+(b-a)*t;
const smoothstep=(a,b,x)=>{const t=clamp((x-a)/(b-a),0,1);return t*t*(3-2*t);}
const normAngle=a=>Math.atan2(Math.sin(a),Math.cos(a));
const angleDelta=(a,b)=>normAngle(a-b);
const rand=(a,b)=>a+Math.random()*(b-a);
```

Terrain class with reset.

```
class Terrain {
  constructor(){ this.reset(); }
  reset(){
    this.startX = -1800;
    this.step = 18;
    this.ys = [];
    this.ramps = [];
    this.nextRamp = 1100;
    this.lastX = this.startX - this.step;
    this.extendTo(1600);
  }
  extendTo(x){
    while (this.lastX < x) {
      this.lastX += this.step;
      const px = this.lastX;
      if (px > this.nextRamp) { ... }
      let y = 0;
      const calm = smoothstep(150, 1000, px);
      y += calm*(52*Math.sin(px*0.00145+0.6) + 26*Math.sin(px*0.0037+2.1) + 10*Math.sin(px*0.0093+0.2));
      y += smoothstep(500, 1500, px)*38*Math.sin(px*0.00051+2.6);
      for (const r of this.ramps){
        const d=(px-r.cx)/r.w;
        if (d>-2.6 && d<2.6) y -= r.amp*Math.exp(-d*d);
      }
      this.ys.push(y);
    }
  }
  yAt(x){
    this.extendTo(x+1400);
    const f=(x-this.startX)/this.step;
    if (f<=0) return this.ys[0];
    const i=Math.floor(f);
    if (i>=this.ys.length-1) return this.ys[this.ys.length-1];
    const t=f-i;
    return this.ys[i]*(1-t)+this.ys[i+1]*t;
  }
  slopeAt(x){ const d=24; return Math.atan2(this.yAt(x+d)-this.yAt(x-d), 2*d); }
}
