  --gold: #ffc857;
  --panel: rgba(26, 13, 32, 0.86);
  --line: rgba(255, 214, 170, 0.18);
  --font: ui-rounded, "Trebuchet MS", "Segoe UI", system-ui, -apple-system, sans-serif;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", "Roboto Mono", Menlo, monospace;
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--ink);
  color: var(--cream);
  font-family: var(--font);
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  touch-action: none;
  overscroll-behavior: none;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
}

canvas {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
}

.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(125% 95% at 50% 42%, transparent 42%, rgba(8, 3, 14, 0.5) 100%),
    linear-gradient(to bottom, rgba(10, 4, 18, 0.28), transparent 22%);
}

/* ---------- HUD ---------- */

.hud {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: calc(14px + env(safe-area-inset-top, 0px)) calc(16px + env(safe-area-inset-right, 0px)) 0 calc(16px + env(safe-area-inset-left, 0px));
  pointer-events: none;
  transition: opacity 0.35s ease, transform 0.35s ease;
}

body[data-state="menu"] .hud {
  opacity: 0;
  transform: translateY(-8px);
}

.hud-block {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.hud-block.right {
  flex-direction: row;
  align-items: center;
  gap: 8px;
}

.stat {
  display: flex;
  align-items: baseline;
  gap: 9px;
}

.label {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.22em;
  color: var(--gold);
  text-shadow: 0 1px 6px rgba(0, 0, 0, 0.5);
}

.value {
  font-family: var(--mono);
  font-size: clamp(22px, 5vw, 30px);
  font-weight: 800;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 2px 14px rgba(0, 0, 0, 0.55);
}

.stat.small .value {
  font-size: clamp(15px, 3.4vw, 19px);
  color: var(--muted);
}

.substat {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: rgba(255, 233, 207, 0.72);
  text-shadow: 0 1px 5px rgba(0, 0, 0, 0.5);
}

.dot {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--orange);
}

.speed {
  width: 112px;
  height: 4px;
  margin-top: 5px;
  border-radius: 99px;
  background: rgba(255, 233, 207, 0.14);
  overflow: hidden;
}

.speed i {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--gold), var(--orange), var(--pink));
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.08s linear;
}

.icon-btn {
  pointer-events: auto;
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: rgba(24, 12, 30, 0.55);
  backdrop-filter: blur(8px);
