.icon-btn:hover { background: rgba(48, 24, 56, 0.8); }
.icon-btn:active { transform: scale(0.94); }

.icon-btn svg {
  width: 18px;
  height: 18px;
  fill: currentColor;
}

.icon-btn svg .wave {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
}

.icon-btn svg .slash { display: none; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }

body.muted .icon-btn svg .wave { display: none; }
body.muted .icon-btn svg .slash { display: block; }

/* ---------- Touch controls ---------- */

.touch-controls {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  align-items: flex-end;
