}

.control .cap {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: rgba(255, 233, 207, 0.7);
}

.control.gas {
  border-color: rgba(255, 140, 90, 0.4);
  background: radial-gradient(circle at 50% 35%, rgba(120, 46, 52, 0.62), rgba(38, 14, 30, 0.7));
}

