.control.active {
  transform: scale(0.93);
  border-color: rgba(255, 216, 160, 0.75);
  background: radial-gradient(circle at 50% 35%, rgba(150, 64, 60, 0.8), rgba(52, 18, 36, 0.85));
}

@media (hover: hover) and (pointer: fine) {
  .control {
    width: 76px;
    height: 76px;
    opacity: 0.55;
  }
  .control:hover { opacity: 1; }
}

/* ---------- Overlay ---------- */

.overlay {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  padding: calc(18px + env(safe-area-inset-top, 0px)) 18px calc(18px + env(safe-area-inset-bottom, 0px));
  background: radial-gradient(90% 80% at 50% 45%, rgba(20, 8, 28, 0.34), rgba(10, 4, 16, 0.78));
  backdrop-filter: blur(5px);
