Let me write updateBike in detail:

```js
function updateBike(dt) {
  if (bike.dead) { updateCrash(dt); return; }

  const gas = input.gas;
  const brake = input.brake;

  if (bike.onGround) {
    const slope = terrain.slopeAt(bike.x);
    let accel = 0;
    if (gas) accel += 820;
    if (brake) accel -= 1600;
    bike.vx += accel * dt;
    bike.vx += 1050 * Math.sin(slope) * dt;
    bike.vx *= Math.exp(-0.7 * dt);
    bike.vx = clamp(bike.vx, -200, MAX_SPEED);

    const prevAngle = bike.angle;
    bike.x += bike.vx * dt;

    const c = Math.cos(bike.angle) * WHEELBASE * 0.5;
    const xr = bike.x - c, xf = bike.x + c;
    const yr = terrain.yAt(xr), yf = terrain.yAt(xf);
    const gy = (yr + yf) * 0.5;
    const slopeNow = Math.atan2(yf - yr, Math.max(20, xf - xr));
    const restY = gy - WHEEL_R;
    const drop = restY - bike.y;

    if (drop > Math.max(3.5, 140 * dt) && Math.abs(bike.vx) > 70) {
      // launch
      bike.onGround = false;
      bike.vy = bike.vx * Math.tan(prevAngle) - 30;
      bike.angVel = 0;
      bike.airRot = 0;
      bike.airTime = 0;
      audio.jump();
      spawnDust(bike.x - 20, bike.y + WHEEL_R, 8, 1);
    } else {
      bike.y = restY;
      bike.vy = 0;
      bike.angle = angleApproach(bike.angle, slopeNow, 1 - Math.exp(-15 * dt));
      bike.wheelSpin += (bike.vx * dt) / WHEEL_R;
      // dust
      if (Math.abs(bike.vx) > 90 && gas) {
        dustAccum += dt * Math.min(60, Math.abs(bike.vx) * 0.08);
        while (dustAccum > 1) { spawnDust(...,1); dustAccum -= 1; }
      }
      if (Math.abs(bike.vx) > 520) maybe speed shake? no
    }
  } else {
    bike.airTime += dt;
    bike.vy += GRAVITY * dt;
    bike.x += bike.vx * dt;
    bike.y += bike.vy * dt;

    let torque = 0;
    if (gas) torque -= 6.2;
    if (brake) torque += 6.2;
    bike.angVel += torque * dt;
    bike.angVel *= Math.exp(-0.25 * dt);
    bike.angVel = clamp(bike.angVel, -10, 10);
    const dA = bike.angVel * dt;
    bike.angle = normAngle(bike.angle + dA);
    bike.airRot += dA;
    bike.wheelSpin += (bike.vx * dt) / WHEEL_R * 0.6;
    bike.vy += 0; // gravity done

    // landing check
    const c = Math.cos(bike.angle) * WHEELBASE * 0.5;
    const gy = (terrain.yAt(bike.x - c) + terrain.yAt(bike.x + c)) * 0.5;
    const restY = gy - WHEEL_R;
    if (bike.y >= restY) {
      const slope = terrain.slopeAt(bike.x);
      const diff = normAngle(bike.angle - slope);
      if (Math.abs(diff) > 1.0) {
        crash();
      } else {
        land(restY, slope, diff);
      }
    }
  }

  run.air += (bike.onGround ? 0 : dt * 22);
  // score/distance
  run.distance = Math.max(run.distance, (bike.x - 160) / 12);
  updateHud(false);
}
```

Wait run.distance should be floor for display; store meters as float and display floor. currentScore uses run.distance. Fine.

Note: when landing at restY, bike.y might be far below (tunnel); setting to restY fine.

`land`:
```js
function land(restY, slope, diff) {
  const impact = Math.abs(bike.vy);
  const airRot = Math.abs(bike.airRot);
