import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';

const errors = [];
const browser = await chromium.launch({ args: ['--use-gl=swiftshader', '--enable-unsafe-swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
await page.waitForTimeout(800);

const menu = await page.evaluate(() => ({
  state: window.__ridge.state,
  hasDebug: !!window.__ridge,
  canvas: [document.querySelector('#game').width, document.querySelector('#game').height],
}));
console.log('menu:', JSON.stringify(menu));

await page.click('#play');
await page.waitForTimeout(400);

// Ride under gas for 6 seconds of simulated play.
await page.evaluate(() => window.__ridge.setInput(true, false));
await page.waitForTimeout(6000);

const run = await page.evaluate(() => ({
  state: window.__ridge.state,
  x: Math.round(window.__ridge.bike.x),
  speed: Math.round(window.__ridge.bike.vx),
  score: document.querySelector('#score').textContent,
  distance: document.querySelector('#distance').textContent,
  terrain: window.__ridge.terrain.length,
  particles: window.__ridge.particles.length,
  launches: window.__ridge.telemetry.launches.length,
  landings: window.__ridge.telemetry.landings.length,
}));
console.log('run:', JSON.stringify(run));

await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-play.png' });

// Pause / resume sanity.
await page.evaluate(() => window.__ridge.pause());
await page.waitForTimeout(300);
const paused = await page.evaluate(() => window.__ridge.state);
await page.evaluate(() => window.__ridge.resume());
await page.waitForTimeout(300);
const resumed = await page.evaluate(() => window.__ridge.state);
console.log('pause:', paused, '-> resume:', resumed);

// Let it crash or just restart to exercise the over screen.
await page.evaluate(() => window.__ridge.setInput(false, false));
await page.evaluate(() => window.__ridge.start());
await page.waitForTimeout(700);
const restarted = await page.evaluate(() => ({ state: window.__ridge.state, x: Math.round(window.__ridge.bike.x) }));
console.log('restarted:', JSON.stringify(restarted));

console.log('errors:', errors.length ? errors : 'none');
await browser.close();

